import{_ as t,o as s,c as r,a2 as n}from"./chunks/framework.BXyf8PVu.js";const g=JSON.parse('{"title":"ESG","description":"","frontmatter":{"title":"ESG"},"headers":[],"relativePath":"fr/blogs/CFA/C4 Corporate Finance/M2 ESG.md","filePath":"fr/blogs/CFA/C4 Corporate Finance/M2 ESG.md"}'),i={name:"fr/blogs/CFA/C4 Corporate Finance/M2 ESG.md"};function a(o,e,l,d,u,c){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="facteurs-environnementaux-sociaux-et-de-gouvernance-esg-dans-l-analyse-d-investissement" tabindex="-1">Facteurs environnementaux, sociaux et de gouvernance (ESG) dans l’analyse d’investissement <a class="header-anchor" href="#facteurs-environnementaux-sociaux-et-de-gouvernance-esg-dans-l-analyse-d-investissement" aria-label="Permalink to &quot;Facteurs environnementaux, sociaux et de gouvernance (ESG) dans l’analyse d’investissement&quot;">​</a></h1><p>Comment les structures d’actionnariat façonnent la gouvernance d’entreprise, comment évaluer la gouvernance d’une entreprise, et comment identifier les risques et les opportunités ESG et les intégrer à l’analyse des actions et du crédit. Le module est conceptuel : il n’y a pas de formules à mémoriser.</p><table tabindex="0"><thead><tr><th>Terme</th><th>Signification</th></tr></thead><tbody><tr><td><strong>Actionnaires de contrôle</strong></td><td>Une personne ou un groupe (une famille, d’autres entreprises, l’État) capable d’exercer le contrôle, en détenant soit la <strong>majorité</strong> (&gt; 50 %) <strong>soit une minorité</strong> (&lt; 50 %) des actions</td></tr><tr><td><strong>Problème principal–agent</strong></td><td>Les dirigeants utilisent les ressources de l’entreprise dans leur propre intérêt plutôt que dans celui des actionnaires</td></tr><tr><td><strong>Problème principal–principal</strong></td><td>Les actionnaires de contrôle s’approprient des ressources au détriment des actionnaires minoritaires</td></tr><tr><td><strong>Plafonds de droits de vote</strong></td><td>Limites légales aux votes des grosses participations (souvent utilisées par les États pour dissuader le contrôle étranger d’entreprises stratégiques)</td></tr><tr><td><strong>Administrateurs croisés</strong></td><td>Les mêmes personnes siègent aux conseils de plusieurs entreprises (courant en Amérique latine)</td></tr><tr><td><strong>Initiés</strong></td><td>Dirigeants et administrateurs qui sont aussi actionnaires</td></tr><tr><td><strong>Activisme actionnarial</strong></td><td>Stratégies utilisées par les actionnaires pour pousser une entreprise à agir d’une certaine façon</td></tr><tr><td><strong>Intégration ESG</strong></td><td>L’utilisation de facteurs ESG, qualitatifs et quantitatifs, dans l’analyse des titres et des secteurs <strong>et dans la construction de portefeuille</strong></td></tr><tr><td><strong>Actifs échoués</strong></td><td>Actifs devenus obsolètes ou non rentables, souvent à cause de la réglementation ou de l’évolution de la demande</td></tr><tr><td><strong>Écoblanchiment</strong></td><td>Le risque que le produit d’une obligation verte ne finance pas réellement un projet bénéfique pour l’environnement</td></tr></tbody></table><h2 id="structure-de-l-actionnariat" tabindex="-1">Structure de l’actionnariat <a class="header-anchor" href="#structure-de-l-actionnariat" aria-label="Permalink to &quot;Structure de l’actionnariat&quot;">​</a></h2><ul><li><strong>Actionnariat dispersé</strong> : de nombreux actionnaires, aucun ne pouvant exercer seul le contrôle.</li><li><strong>Actionnariat concentré</strong> : un actionnaire ou un groupe (les actionnaires de contrôle) peut exercer le contrôle.</li><li><strong>Hybride</strong> : entre les deux.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Il n’existe pas de seuils fixes en pourcentage. La détention seule peut ne pas montrer qui contrôle une entreprise : les actionnaires de contrôle peuvent détenir <strong>la majorité ou une minorité</strong> des actions, grâce aux mécanismes ci-dessous. (Le seul « 25 % » de la lecture décrit le Royaume-Uni, où peu d’entreprises ont un actionnaire détenant 25 % ou plus.)</p></div><p>L’actionnariat concentré est bien plus courant : <strong>38 des 47</strong> juridictions étudiées par l’OCDE (2017).</p><table tabindex="0"><thead><tr><th>Classification</th><th>Juridictions</th><th>Remarques</th></tr></thead><tbody><tr><td><strong>Dispersé</strong></td><td>Australie, Irlande, Royaume-Uni, États-Unis</td><td>Australie : actions détenues surtout par des institutions financières ; les sociétés cotées américaines ont rarement un actionnaire de contrôle</td></tr><tr><td><strong>Hybride</strong></td><td>Canada, Allemagne, Japon, Pays-Bas, Suisse</td><td>P. ex. Allemagne : beaucoup d’entreprises étroitement contrôlées, mais des actions cotées largement détenues</td></tr><tr><td><strong>Concentré</strong></td><td>Les 38 autres (p. ex. Chine, France, Inde, Brésil, Corée du Sud)</td><td>État : Chine, Norvège, Suède. Familles : Brésil, Mexique, Portugal, Corée du Sud. Groupes d’entreprises : Inde, Russie</td></tr></tbody></table><p><strong>Comment le contrôle peut dépasser la détention :</strong></p><ul><li><strong>Détention horizontale</strong> : des entreprises ayant des intérêts commerciaux communs (clients ou fournisseurs clés) détiennent des actions les unes des autres. Elle soutient les alliances stratégiques et les relations de long terme.</li><li><strong>Détention verticale (pyramidale)</strong> : une entreprise ou un groupe contrôle deux sociétés holding ou plus, qui contrôlent à leur tour des sociétés opérationnelles.</li><li><strong>Actions à droits de vote multiples</strong> : une catégorie a des droits de vote supérieurs (ou exclusifs), les autres des droits inférieurs ou nuls. Combinée à une pyramide, cette structure permet au groupe au sommet de s’attribuer les actions à vote supérieur et de contrôler les sociétés opérationnelles en détenant relativement peu d’actions.</li></ul><h3 id="conflits-selon-la-structure-de-l-actionnariat" tabindex="-1">Conflits selon la structure de l’actionnariat <a class="header-anchor" href="#conflits-selon-la-structure-de-l-actionnariat" aria-label="Permalink to &quot;Conflits selon la structure de l’actionnariat&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Détention</th><th>Pouvoir de vote</th><th>Rapport de force</th><th>Conflit principal</th></tr></thead><tbody><tr><td>Dispersée</td><td>Dispersé</td><td>Actionnaires faibles, <strong>dirigeants forts</strong></td><td><strong>Principal–agent</strong></td></tr><tr><td>Concentrée</td><td>Concentré</td><td><strong>Actionnaires forts</strong>, dirigeants faibles</td><td><strong>Principal–principal</strong></td></tr><tr><td>Dispersée</td><td>Concentré</td><td>Actionnaires de contrôle <strong>sans majorité</strong> (actions à vote multiple, pyramides)</td><td><strong>Principal–principal</strong></td></tr><tr><td>Concentrée</td><td>Dispersé</td><td>Résulte des <strong>plafonds de droits de vote</strong></td><td>(non nommé dans la lecture)</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Les actionnaires de contrôle <strong>réduisent</strong> le problème principal–agent (ils contrôlent le conseil, nomment les dirigeants et ont intérêt à surveiller), mais ils <strong>créent</strong> le problème principal–principal.</p></div><h3 id="actionnaires-influents" tabindex="-1">Actionnaires influents <a class="header-anchor" href="#actionnaires-influents" aria-label="Permalink to &quot;Actionnaires influents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Actionnaire</th><th>Rôle et préoccupations</th></tr></thead><tbody><tr><td><strong>Banques</strong></td><td>Courantes en Europe et en Asie ; à la fois prêteuses <strong>et</strong> actionnaires. Peuvent pousser l’entreprise à contracter de gros prêts à des conditions défavorables, au détriment des autres actionnaires</td></tr><tr><td><strong>Familles</strong></td><td>Prédominantes en Amérique latine, moins en Asie et en Europe ; souvent avec des administrateurs croisés. <strong>+</strong> moins de problèmes principal–agent. <strong>−</strong> faible transparence, faible responsabilité de la direction, peu d’égard pour les droits des minoritaires, difficulté à attirer les meilleurs dirigeants</td></tr><tr><td><strong>Entreprises publiques</strong></td><td>Dans les secteurs stratégiques, là où les besoins en capital dépassent le secteur privé, ou là où l’État veut des produits à un prix ou une norme fixés (énergie, santé). Une entreprise publique cotée (<strong>actionnariat mixte</strong>) subit moins la discipline du marché (garantie implicite de l’État contre la faillite) et peut poursuivre des politiques publiques au détriment des actionnaires</td></tr><tr><td><strong>Investisseurs institutionnels</strong></td><td>Fonds communs, fonds de pension, assureurs, hedge funds ; ont les ressources et l’expertise pour juger. Rarement assez gros pour contrôler dans les marchés dispersés, mais favorisent la bonne gouvernance en tenant conseils et dirigeants responsables</td></tr><tr><td><strong>Groupes d’entreprises</strong></td><td>Les structures horizontales ou verticales donnent un contrôle disproportionné par rapport à la détention ; les participations croisées restreignent les cessions d’actions et tiennent les étrangers à l’écart. Risque accru de <strong>transactions avec des parties liées</strong> au détriment des minoritaires (p. ex. Samsung, Sanwa, Grupo Carso)</td></tr><tr><td><strong>Capital-investissement</strong></td><td>Capital-risque (premiers stades, supervision) et fonds de LBO (contrôle majoritaire d’entreprises matures) ; peuvent apporter des codes de conduite et une rémunération liée à la performance</td></tr><tr><td><strong>Investisseurs étrangers</strong></td><td>Influents dans les marchés émergents lorsqu’ils détiennent plus que les investisseurs nationaux ; ceux issus de juridictions plus strictes peuvent exiger plus de transparence. Une double cotation sur un marché plus strict peut profiter aux minoritaires locaux</td></tr><tr><td><strong>Initiés</strong></td><td>Participations plus importantes → meilleur alignement avec les actionnaires et vision de long terme ; mais de grosses participations peuvent aussi leur donner le pouvoir de protéger leurs propres intérêts</td></tr></tbody></table><h3 id="effets-sur-la-gouvernance" tabindex="-1">Effets sur la gouvernance <a class="header-anchor" href="#effets-sur-la-gouvernance" aria-label="Permalink to &quot;Effets sur la gouvernance&quot;">​</a></h3><ul><li><strong>Administrateurs indépendants</strong> : administrateurs sans relation significative avec l’entreprise (emploi, détention ou rémunération). Ils sont nés dans les juridictions à actionnariat dispersé pour renforcer la surveillance des dirigeants, et leur part a augmenté après des scandales comme Enron. Les États-Unis exigent des comités d’audit, de nomination et de rémunération composés entièrement d’administrateurs indépendants. Dans la plupart des juridictions à actionnariat concentré, les comités de nomination et de rémunération ne sont pas obligatoires, et les administrateurs indépendants jouent un rôle plus restreint. Les pays de l’OCDE exigent ou recommandent soit un nombre minimal (en général 1 à 3), soit une proportion minimale (en général de 20 % à plus de 50 %).</li><li><strong>Structure du conseil</strong> : <ul><li><strong>Moniste</strong> : un conseil unique d’administrateurs exécutifs et non exécutifs. La structure la plus courante.</li><li><strong>Dualiste</strong> : un conseil de surveillance contrôle un directoire. Obligatoire p. ex. en Argentine, en Allemagne et en Russie ; facultatif au Brésil et en France. Le conseil de surveillance examine les comptes, revoit le rapport annuel, supervise les auditeurs et fixe ou influence la rémunération de la direction ; en Allemagne, il comprend des représentants des parties prenantes (banques, salariés).</li></ul></li><li><strong>Dispositifs de vote spéciaux</strong> : aident les minoritaires à participer à la nomination et à l’élection des administrateurs (p. ex. Brésil, Inde, Portugal, Turquie, Italie, Israël, Royaume-Uni). Au Royaume-Uni, une société de la cote premium ayant un actionnaire de contrôle doit faire approuver ses administrateurs indépendants <strong>à la fois</strong> par l’ensemble des actionnaires <strong>et</strong> par les actionnaires sans contrôle.</li><li><strong>Codes de gouvernance, lois et règles de cotation</strong> : les codes nationaux fonctionnent selon le principe <strong>appliquer ou expliquer</strong>. Le Japon va plus loin : une entreprise sans administrateurs externes doit expliquer pourquoi en nommer ne serait pas approprié. En l’absence de code national, c’est le droit des sociétés (p. ex. Chili) ou le règlement de la bourse (p. ex. Inde) qui s’applique.</li><li><strong>Codes de gestion responsable (stewardship)</strong> : des codes surtout volontaires qui encouragent les investisseurs à exercer leurs droits et à dialoguer. Selon le UK Stewardship Code, les investisseurs institutionnels doivent suivre les entreprises dans lesquelles ils investissent, et les gérants britanniques doivent publier une déclaration appliquer-ou-expliquer.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Le problème principal–agent est en général <strong>plus faible</strong> dans un actionnariat concentré, ce qui explique pourquoi les administrateurs indépendants y jouent un rôle plus restreint.</p></div><h2 id="evaluer-la-gouvernance-d-entreprise" tabindex="-1">Évaluer la gouvernance d’entreprise <a class="header-anchor" href="#evaluer-la-gouvernance-d-entreprise" aria-label="Permalink to &quot;Évaluer la gouvernance d’entreprise&quot;">​</a></h2><p>Une gouvernance efficace peut apporter une meilleure rentabilité et une croissance du ROE, un meilleur accès au crédit, des dividendes plus élevés et durables, une bonne performance boursière à long terme et un <strong>coût du capital plus faible</strong>. Une gouvernance inefficace entraîne une atteinte à la réputation, une moindre compétitivité, un cours faible ou volatil, une rentabilité plus faible et un <strong>coût du capital plus élevé</strong>.</p><p>La gouvernance est difficile à quantifier. Commencez par les politiques publiées (y compris l’éthique des affaires, la corruption, la protection des lanceurs d’alerte et les transactions avec des parties liées), puis dialoguez avec la direction, et recourez à l’activisme si nécessaire. En pratique, les analystes reflètent la gouvernance en ajustant la <strong>prime de risque (coût du capital) ou le spread de crédit</strong>.</p><h3 id="politiques-et-pratiques-du-conseil" tabindex="-1">Politiques et pratiques du conseil <a class="header-anchor" href="#politiques-et-pratiques-du-conseil" aria-label="Permalink to &quot;Politiques et pratiques du conseil&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Domaine</th><th>Ce qu’il faut examiner</th></tr></thead><tbody><tr><td><strong>Cumul des fonctions de PDG</strong></td><td>Le directeur général préside aussi le conseil → la surveillance du conseil peut en souffrir. Si le président n’est pas indépendant, un <strong>administrateur indépendant référent</strong> peut être nommé</td></tr><tr><td><strong>Indépendance du conseil</strong></td><td>Aucun administrateur indépendant, ou une minorité seulement, est un point <strong>négatif</strong> : la direction peut agir dans son propre intérêt → risque perçu plus élevé</td></tr><tr><td><strong>Comités</strong></td><td>Audit, gouvernance, rémunération, nomination, risques, conformité. Vérifiez que les comités clés sont indépendants : des membres non indépendants ou exécutifs créent des conflits sur la rémunération (comité des rémunérations), le choix des dirigeants (comité des nominations) et l’intégrité de l’information (comité d’audit)</td></tr><tr><td><strong>Compétences et expérience</strong></td><td>Des compétences trop concentrées, ou variées mais sans lien avec le cœur de métier, peuvent toutes deux être insuffisantes. Dans les secteurs des ressources ou à fort risque ESG, les conseils comprennent en général une expertise environnementale, climatique ou sociale</td></tr><tr><td><strong>Ancienneté</strong></td><td>Plus de <strong>10 ans</strong> est long. <strong>+</strong> connaissance approfondie de l’activité et du bilan de la direction ; <strong>−</strong> peut affaiblir l’indépendance (trop proche de la direction) et freiner le changement</td></tr><tr><td><strong>Composition</strong></td><td>Nombre et diversité des administrateurs (parcours professionnel, culturel et géographique, genre, âge, ancienneté). Trop de membres ou trop peu de diversité peuvent nuire à l’efficacité</td></tr><tr><td><strong>Évaluation du conseil</strong></td><td>Autoévaluation ou évaluation externe, portant sur les missions, le leadership, la structure (y compris les comités) et les relations entre le conseil et la direction ; peut s’adresser aux actionnaires, aux régulateurs ou à d’autres parties prenantes</td></tr></tbody></table><p><strong>Rémunération des dirigeants.</strong> Examinez la transparence ; les critères des incitations de court et de long terme ; le lien avec la stratégie de l’entreprise ; et l’écart de rémunération entre le directeur général et le salarié moyen. Une rémunération excessive (souvent rémunération du DG ÷ rémunération moyenne) se juge au regard des KPI : les incitations créent-elles de la valeur pour l’entreprise ?</p><ul><li><strong>Say on pay</strong> : les <strong>actionnaires</strong> peuvent voter ou s’exprimer sur la rémunération.</li><li><strong>Clawback</strong> : l’entreprise peut <strong>récupérer une rémunération déjà attribuée</strong> si des retraitements, des fautes, des infractions à la loi ou des défaillances de gestion des risques sont révélés.</li></ul><p><strong>Droits de vote.</strong> <strong>Vote simple</strong> (une action, une voix) contre actions <strong>à droits de vote multiples</strong>, où les fondateurs ou dirigeants détiennent des actions à vote plus élevé que le public : un conflit potentiel avec les minoritaires.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Séparer les fonctions de directeur général et de président est positif, mais ce n’est pas tout : une faible indépendance, une longue ancienneté et la domination d’une famille ou d’initiés peuvent encore rendre un conseil faible.</p></div><h2 id="identifier-les-facteurs-esg" tabindex="-1">Identifier les facteurs ESG <a class="header-anchor" href="#identifier-les-facteurs-esg" aria-label="Permalink to &quot;Identifier les facteurs ESG&quot;">​</a></h2><p>La principale difficulté est d’obtenir une information <strong>pertinente, comparable et utile à la décision</strong>. Les données ESG proviennent surtout des documents publics et des rapports de durabilité (qui peuvent ou non faire l’objet d’une assurance indépendante) ; la plupart des informations ESG sont <strong>volontaires</strong> et <strong>hétérogènes</strong>, même si elles ont augmenté avec le temps.</p><p><strong>Matérialité.</strong> Une question ESG est significative si elle devrait affecter l’activité de l’entreprise, sa performance financière et la valorisation de ses titres, positivement ou négativement. Les entreprises peuvent qualifier de « significative » une information positive mais sans importance, tout en minimisant des informations négatives que les investisseurs jugeraient significatives.</p><p><strong>Horizon d’investissement.</strong> L’importance d’une question dépend aussi de l’horizon :</p><ul><li>L’horizon compte particulièrement pour les <strong>analystes crédit</strong>, car les obligations ont des échéances différentes.</li><li>L’horizon d’une question peut passer du long terme au court terme (ou l’inverse) après un changement de réglementation ou une controverse comme une marée noire.</li><li>P. ex. un industriel fait face à des règles environnementales plus strictes à l’avenir : un investisseur de court terme y voit peu d’effet sur le bénéfice à court terme ; un investisseur de long terme s’attend à des modernisations d’usines coûteuses ou à des amendes.</li></ul><p><strong>Facteurs pertinents selon le secteur.</strong> Les meilleures pratiques de gouvernance sont assez homogènes d’une entreprise à l’autre (même si elles varient selon les régions). Pour les facteurs environnementaux et sociaux, il n’existe <strong>pas de meilleure pratique mondiale</strong> : la pertinence dépend du secteur. Les entreprises énergétiques sont plus exposées aux facteurs <strong>environnementaux</strong> ; les banques aux facteurs <strong>sociaux</strong> (sécurité des données, vie privée, satisfaction des clients) ; toutes deux à la gouvernance.</p><p><strong>Trois façons d’identifier les facteurs ESG</strong> (seules ou combinées) :</p><table tabindex="0"><thead><tr><th>Approche</th><th>Ce que c’est</th><th>Exemples</th></tr></thead><tbody><tr><td><strong>Méthodes propriétaires</strong></td><td>Le jugement et les outils propres de l’analyste ou de la société, à partir des entreprises, de la presse, des groupes sectoriels et environnementaux, des syndicats, des experts et de l’État</td><td>Rapports annuels, de durabilité et de procuration, 10-K ; publications de scénarios climatiques alignées sur la TCFD (risques de transition et risques physiques)</td></tr><tr><td><strong>Fournisseurs de données ESG</strong></td><td>Des prestataires transforment les informations publiques en scores et classements ESG (souvent relatifs au secteur), avec une part d’évaluation subjective par des analystes</td><td>MSCI, Sustainalytics</td></tr><tr><td><strong>Initiatives à but non lucratif et cadres de reporting</strong></td><td>Données, analyses et outils sur les questions ESG</td><td>IIRC (cadre de reporting standardisé), GRI (normes de reporting de durabilité par secteur), SASB (normes comptables de durabilité uniformes ; <strong>cartes de matérialité</strong>), 2DII, Access to Nutrition Index</td></tr></tbody></table><p>Les informations publiées vont du minimum à de nombreuses pages, ce qui rend les comparaisons difficiles. Par exemple, les thèmes de la GRI pour les biens de consommation durables et les produits ménagers et d’hygiène comprennent des thèmes environnementaux (approvisionnement en matières, emballages, plastiques et produits chimiques, efficacité énergétique des produits), sociaux (travailleurs migrants, sécurité des produits, étiquetage, déchets électroniques) et autres (rémunération des dirigeants, genre dans les organes de gouvernance, sélection des fournisseurs).</p><h2 id="integration-esg" tabindex="-1">Intégration ESG <a class="header-anchor" href="#integration-esg" aria-label="Permalink to &quot;Intégration ESG&quot;">​</a></h2><p>L’intégration ESG vise à repérer des opportunités et à réduire le risque baissier.</p><table tabindex="0"><thead><tr><th></th><th>Actions</th><th>Obligations (crédit)</th></tr></thead><tbody><tr><td>Objectif</td><td>Repérer des <strong>opportunités et</strong> réduire le risque baissier</td><td>Surtout <strong>réduire le risque baissier</strong> (le meilleur cas est le remboursement au pair)</td></tr><tr><td>Techniques</td><td>Prévoir les états financiers et les ratios, ajuster les paramètres de valorisation (p. ex. le <strong>taux d’actualisation</strong>), analyse de sensibilité et de scénarios</td><td>Évaluations de crédit internes, ratios prévisionnels, classement relatif du crédit ; valeur relative, <strong>spread</strong>, <strong>duration</strong>, analyse de sensibilité et de scénarios</td></tr><tr><td>Illustrations</td><td>Hôtel : augmenter les coûts d’exploitation en raison d’une forte rotation du personnel. Fabricant de snacks : <strong>abaisser</strong> le taux d’actualisation après le passage à un ingrédient clé durable</td><td>Fabricant de jouets : des procès dégradent les ratios de crédit, les flux de trésorerie et la liquidité ; les spreads peuvent s’élargir. Entreprise charbonnière : le risque d’actifs échoués pèse bien plus sur ses titres à <strong>10 ans</strong> que sur ceux à <strong>1 an</strong></td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>L’identification et l’intégration se ressemblent pour les actions et le crédit, mais les <strong>facteurs significatifs et leurs implications diffèrent</strong>, et l’effet sur le crédit (et les CDS) peut varier selon l’<strong>échéance</strong>.</p></div><h3 id="obligations-vertes" tabindex="-1">Obligations vertes <a class="header-anchor" href="#obligations-vertes" aria-label="Permalink to &quot;Obligations vertes&quot;">​</a></h3><p>Une <strong>obligation verte</strong> finance des projets ayant des bénéfices environnementaux ou climatiques : son produit est affecté à des projets verts précis.</p><ul><li>La première est la Climate Awareness Bond de la Banque européenne d’investissement, en <strong>2007</strong>.</li><li>L’émetteur décide du label « vert » avec son chef de file, doit publier les critères d’éligibilité et l’usage des fonds, et peut commander des revues indépendantes. Les <strong>Green Bond Principles</strong> (2014 ; volontaires ; gérés par l’ICMA) encadrent ce processus ; les fournisseurs d’indices, les agences de notation et la Climate Bonds Initiative ont leurs propres méthodes, et la Commission européenne élabore des critères.</li><li>Pour l’émetteur : des coûts de suivi et de reporting supplémentaires, mais une base d’investisseurs plus large et potentiellement un rendement plus faible à l’émission.</li><li>Formes : obligations d’entreprise classiques, obligations de projet, MBS/ABS et obligations municipales (p. ex. l’obligation verte de garantie générale de US$300 millions de la Californie en 2014, adossée au fonds général comme ses autres obligations GO).</li><li><strong>Même notation et même valorisation</strong> que les obligations classiques de l’émetteur (toutes choses égales par ailleurs) : seul l’usage des fonds diffère, et les porteurs ont le même recours.</li><li>Peut se négocier avec une prime (spread plus serré) <strong>à cause de la demande</strong>, pas parce qu’elle est moins risquée.</li><li>Risques : <strong>écoblanchiment</strong> (payer trop cher une caractéristique verte, ou détenir une obligation qui ne respecte pas un mandat environnemental) et <strong>liquidité</strong> (beaucoup de porteurs achètent et conservent).</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Le risque de crédit d’une obligation verte est celui de l’émetteur. Un spread plus serré reflète la <strong>demande</strong>, pas un risque de défaut plus faible.</p></div><h2 id="evaluer-les-risques-et-opportunites-esg" tabindex="-1">Évaluer les risques et opportunités ESG <a class="header-anchor" href="#evaluer-les-risques-et-opportunites-esg" aria-label="Permalink to &quot;Évaluer les risques et opportunités ESG&quot;">​</a></h2><p>Le processus d’intégration :</p><ol><li>Identifier les facteurs ESG <strong>significatifs</strong> pour l’entreprise et son secteur.</li><li>Les évaluer dans le temps, dans les prévisions et par rapport aux pairs.</li><li>Ajuster les états financiers et la valorisation :</li></ol><table tabindex="0"><thead><tr><th>Où</th><th>Ajustements ESG typiques</th></tr></thead><tbody><tr><td>Compte de résultat / flux de trésorerie</td><td>Chiffre d’affaires, coûts d’exploitation et hors exploitation, marges, bénéfices, investissements</td></tr><tr><td>Bilan</td><td>Estimations d’<strong>actifs dépréciés</strong></td></tr><tr><td>Valorisation des actions</td><td>Coût du capital / <strong>taux d’actualisation</strong>, multiple de cours, valeur terminale</td></tr><tr><td>Valorisation des obligations</td><td><strong>Spread de crédit</strong> ou CDS</td></tr></tbody></table><p>Le cadre <em>Guidance and Case Studies for ESG Integration: Equities and Fixed Income</em> (2018) couvre la recherche (qualitative et quantitative), la valorisation des titres, la construction de portefeuille, l’allocation d’actifs, l’analyse de scénarios et la gestion des risques.</p><p>Les trois cas de la lecture portent chacun sur un pilier ; les idées s’appliquent à d’autres secteurs :</p><table tabindex="0"><thead><tr><th>Cas</th><th>Pilier</th><th>Indicateur clé</th><th>Ajustement financier</th><th>Effet sur la valorisation</th></tr></thead><tbody><tr><td><strong>Frizzle Drinks</strong> (boissons, États-Unis)</td><td>Environnement</td><td><strong>Intensité en eau</strong> = litres d’eau par litre de produit (normalisée par million USD de chiffre d’affaires pour comparer aux pairs)</td><td>En baisse de 27 % de 2009 à 2021, objectif de 13 % de plus d’ici 2025. Coût des ventes/chiffre d’affaires 2022P de 40 % (pairs 42 %), réduit de 1 % grâce à une moindre consommation d’eau → marge brute plus élevée</td><td>Bénéfices plus élevés → juste valeur de l’action plus élevée ; meilleur flux d’exploitation pour les obligations et les CDS ; vérifier si un risque ESG plus faible est <strong>déjà dans les spreads</strong></td></tr><tr><td><strong>Well Pharma</strong> (pharmacie, Europe)</td><td>Social</td><td><strong>Qualité des produits</strong> : controverses, lettres d’avertissement des régulateurs, rappels, amendes, % d’usines certifiées (p. ex. ISO 9001)</td><td>Pire bilan parmi les pairs (15 lettres d’avertissement, 5 controverses sur la qualité). Chiffre d’affaires −2 % l’an prochain ; coût des ventes/chiffre d’affaires +1,3 % ; charges hors exploitation +4,5 % du résultat d’exploitation. Le traitement dépend du caractère <strong>récurrent ou ponctuel</strong> des problèmes</td><td>Bénéfices et flux de trésorerie plus faibles pour les actionnaires <strong>et</strong> les créanciers ; possible dépréciation de la valeur de la marque</td></tr><tr><td><strong>Sumiyoshi</strong> (banque japonaise)</td><td>Gouvernance</td><td>Composition du conseil par rapport aux pairs ; <strong>prêts non performants / total des prêts</strong> comme indicateur indirect de gouvernance</td><td>Ratio de prêts non performants supérieur de 50 pb à celui des pairs</td><td>Prime de risque actions plus élevée ; spread de crédit plus large</td></tr></tbody></table><p>Comment les problèmes de qualité de Well Pharma se répercutent sur les chiffres :</p><table tabindex="0"><thead><tr><th>Facteur</th><th>Impact financier</th></tr></thead><tbody><tr><td>Controverses sur la qualité des produits</td><td>Atteinte à la marque → ventes plus faibles</td></tr><tr><td>Lettres d’avertissement des régulateurs</td><td>Coûts de conformité plus élevés</td></tr><tr><td>Rappels de produits</td><td>Chiffre d’affaires perdu ; coûts de rappel</td></tr><tr><td>Amendes réglementaires</td><td>Provisions pour retours et litiges</td></tr><tr><td>Faible part d’usines certifiées</td><td>Risque accru de problèmes de qualité, de rappels et de coûts</td></tr></tbody></table>',53)])])}const m=t(i,[["render",a]]);export{g as __pageData,m as default};
